// CSD_RATIONALE_BEGIN
// Building on attempt 2 (best: 40.8% accuracy, 81.6% syntax) with three targeted changes:
//
// Fix 1 — Break `!`/`=` loops (addresses 7 malformed_constrained_content and 9 unterminated):
//   After the budget-guard check but before taking a constrained step, convert
//   currentConstrainedOut to a string and use CountSubstring to detect `!` or `=`.
//   Both characters signal a runaway loop: `!` means the model is cycling on factorial
//   or operator-incomplete tokens; `=` means the model tried an assignment and the hard
//   mask forced a bad continuation. On detection, immediately call CloseSpanWithinBudget
//   with all remaining budget so the helper can track the longest completable prefix in
//   its forward pass and emit `>>` there, rather than consuming hundreds of steps on `!`.
//
// Fix 2 — Higher repetition penalty (4.0 → 8.0) and earlier budget guard (80 → 150):
//   A penalty of 4.0 was insufficient to overcome high-logit `!` on the first occurrence.
//   8.0 suppresses it more aggressively. Raising closeReserve from 80 to 150 gives
//   CloseSpanWithinBudget more room to find and reach a completable expression state.
//
// Fix 3 — Stronger int() guidance:
//   Most GSM-symbolic answers require int() around fractional sub-expressions.
//   Updated guidance explicitly says: if a variable is named frac/fraction/rate/mult/etc.
//   and the answer counts whole items, wrap the product in int(). Also reinforce:
//   write ONLY a direct formula from the problem, no algebraic simplification.
//
// Core structure identical to attempt 2: UnconstrainedStep outside spans,
// SafeRepetitionPenaltyStep inside, CloseConstrainedSpan when complete,
// CloseSpanWithinBudget for budget-guard and final cleanup.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (budget-guard or !-loop-detected branch, calls CloseSpanWithinBudget):
//     CloseSpanWithinBudget postcondition: `insideOut ==> parser.IsValidPrefix(currentOut)`.
//     On the closed path ci=false (implication vacuous); on still-open path
//     parser.IsValidPrefix(cc) holds directly. ✓
//
//   (!insideConstrainedOut branch):
//     If next != eosToken and RenderedEndsWith(generated, "<<"), we set
//     currentConstrainedOut := [], satisfying IsValidPrefix([]) by method precondition.
//     Otherwise insideConstrainedOut stays false (vacuous). ✓
//
//   (parser.IsCompletePrefix branch, calls CloseConstrainedSpan):
//     CloseConstrainedSpan sets insideConstrainedOut := false, making the
//     implication vacuously true. ✓
//
//   (normal constrained step, non-EOS):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS.
//     AppendConstrainedToken postcondition: parser.IsValidPrefix(currentOut). ✓
//
//   (final cleanup, calls CloseSpanWithinBudget):
//     Same argument as budget-guard branch. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   (budget-guard / !-loop branch, steps_old = steps before entry):
//     CloseSpanWithinBudget(remaining) postcondition: |cg| <= |generated| + remaining
//     = |generated| + (maxSteps - steps_old).  By inductive hypothesis
//     |generated| <= |generatedPrefix| + steps_old, so
//     |cg| <= |generatedPrefix| + maxSteps.  After steps := maxSteps:
//     |cg| <= |generatedPrefix| + steps. ✓
//
//   (!insideConstrainedOut): steps grows by 1; at most one token appended. ✓
//   (IsCompletePrefix): steps grows by 1; CloseConstrainedSpan appends at most one ">>". ✓
//   (normal constrained step, non-EOS): steps grows by 1; AppendConstrainedToken
//     appends exactly one token; break on EOS (no append). ✓
//   (final cleanup): Same argument as budget-guard branch. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap each intermediate symbolic expression in << >> delimiters. " +
  "End with: The final answer is <<expression>>. " +
  "Inside << >> write exactly one arithmetic expression using only: " +
  "numbers, problem variables, +, -, *, /, //, %, (), int(). " +
  "CRITICAL: If any variable in the expression is a fraction, rate, or multiplier " +
  "(e.g. frac, fraction, rate, mult, multiplier) and the result must be a whole number, " +
  "wrap that sub-expression in int(): e.g. int(n * frac), int(total * fraction). " +
  "For the final answer, use int() if the problem asks for a count of people, items, pages, " +
  "minutes, dollars, or any other whole-number quantity. " +
  "Use // for integer (floor) division when dividing whole quantities. " +
  "Use the exact variable names from the problem. Never substitute numeric values. " +
  "Never write = assignments or if/else inside << >>. " +
  "Write the direct formula from the problem; do not algebraically simplify.");

var closeReserve: nat := 150;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget guard: force-close the span with all remaining steps
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Detect ! or = loop in span content before spending another constrained step
    var spanStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var bangCount := CSDHelpers.CountSubstring(spanStr, "!");
    var eqCount := CSDHelpers.CountSubstring(spanStr, "=");
    if bangCount > 0 || eqCount > 0 {
      // Loop detected: force-close span with remaining budget
      var cg, ci, cc := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
      );
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := maxSteps;
      break;
    } else {
      // Normal constrained step: repetition penalty discourages recycling tokens
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeRepetitionPenaltyStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, generated, 8.0, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(
          lm, parser, generated, currentConstrainedOut, next
        );
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
      }
    }
  }
}

// Final cleanup: close any remaining open span
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

